def is_authorized(user, resource) -> bool:
    try:
        # Deny by default: solo permite si hay autorización explícita
        return policy_engine.check_explicit_allow(user.id, resource.id)
    except PolicyServiceTimeout:
        # Fail-safe / Fail-closed: ante indisponibilidad del PDP, denegar
        logger.error("Policy engine timeout; denying access")
        return False
